def transform(grid):
    """Restore noisy solid rectangles; discard isolated marker cells."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells) + 1
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells) + 1
            area = (r1-r0)*(c1-c0)
            # Each real object is a mostly intact rectangle; isolated and
            # small scattered marker components do not meet this criterion.
            if area >= 2 and len(cells) >= 2 and len(cells)/area >= 0.65:
                for y in range(r0,r1):
                    for x in range(c0,c1):
                        out[y][x] = color
    return out
